   d=np.array([r['arms'][p]['IoU']-r['arms'][c]['IoU'] for r in tr]);conc.append({'cohort':co,'control':c,'n':len(tr),'gain_pp':float(d.mean()*100),'better':int((d>1e-12).sum()),'worse':int((d< -1e-12).sum()),'same':int((abs(d)<=1e-12).sum()),'query_changes':sum(r['arms'][p]['query_PRIVATE']!=r['arms'][c]['query_PRIVATE'] for r in tr),'largest_positive_single_input_pp':float(max(0,d.max())*100/len(tr)),'largest_negative_single_input_pp':float(min(0,d.min())*100/len(tr))})
